    def test_an_import_a_try_makes_a_def_also_names(self, tmp_path):
        """A `try` that imports the name and an `except` that defines it
        bind either: a call of the name reaches one of them, and a plain
        definition after the import is the one that binds."""
        builder = _index(
            tmp_path,
            {
                "pkg/__init__.py": "",
                "pkg/one.py": "class Manager:\n    pass\n\nclass Plain:\n    pass\n",
                "main.py": """
                try:
                    from pkg.one import Manager
                except ImportError:
                    def Manager(*args, **kwargs):
                        return None

                def make():
                    return Manager()

                def plain():
                    from pkg.one import Plain
                    def Plain(*args, **kwargs):
                        return None
                    return Plain()
                """,
            },
        )
        assert _candidates(builder, "FILE:main.py::make") == {
            "REF:pkg.one.Manager": [
                "FILE:main.py::Manager",
                "FILE:pkg/one.py::Manager",
            ]
        }
        assert _calls(builder, "FILE:main.py::plain") == ["FILE:main.py::plain::Plain"]

    def test_a_body_its_head_may_skip_leaves_the_value_open(self, tmp_path):
        """A name a body of an `if`, a loop or a `try` assigns, on the head's
        line or below it, holds after the statement what every way through
        gives where they agree, else no known value. A way that leaves does
        not count, a way of an `if` does not see what another assigns, and a
        `with` body always runs."""
        builder = _index(
            tmp_path,
            {
                "a.py": """
                class A:
                    def use(self): pass
                class B:
                    def use(self): pass

                def same_line(c):
                    x = A()
                    if c: x = B()
                    x.use()

                def below(c):
                    x = A()
                    while c:
                        x = B()
                    x.use()

                def attempt():
                    x = A()
                    try: x = B()
                    except ValueError: pass
                    x.use()

                def other_way(c):
                    x = A()
                    if c: x = B()
                    else: x.use()

                def agreed(c):
                    if c: x = B()
                    else: x = B()
                    x.use()

                def entered(m):
                    x = A()
                    with m: x = B()
                    x.use()

                def leaving():
                    x = A()
                    try:
                        x = B()
                    except ValueError:
                        raise
                    x.use()
                """
            },
        )
        for name in ("same_line", "below", "attempt"):
            assert _calls(builder, f"FILE:a.py::{name}") == [
                "FILE:a.py::A",
                "FILE:a.py::B",
                "REF:x.use",
            ]
        assert _calls(builder, "FILE:a.py::other_way") == [
            "FILE:a.py::A",
            "FILE:a.py::A::use",
            "FILE:a.py::B",
        ]
        assert _calls(builder, "FILE:a.py::agreed") == ["FILE:a.py::B"] * 2 + [
            "FILE:a.py::B::use"
        ]
        for name in ("entered", "leaving"):
            assert _calls(builder, f"FILE:a.py::{name}") == [
                "FILE:a.py::A",
                "FILE:a.py::B",
                "FILE:a.py::B::use",
            ]

