    def test_unannotated_function_returns_what_its_body_does(self, tmp_path):
        """A function without a return annotation returns what its `return`
        statements agree on, `None` aside: an instance, `self`, an
        attribute. A property is read as that. A generator, and a function
        whose returns differ, return neither."""
        builder = _index(
            tmp_path,
            {
                "m.py": """
                class Other:
                    def run(self): ...

                class Job:
                    def run(self): ...

                    def named(self, name):
                        self.name = name
                        return self

                class Queue:
                    def __init__(self):
                        self.head = Job()

                    def first(self):
                        return self.head

                    @property
                    def last(self):
                        return self.head

                def make(flag):
                    if flag:
                        return None
                    return Job()

                def either(flag):
                    if flag:
                        return Job()
                    return Other()

                def each():
                    yield Job()

                def run(queue: Queue):
                    make(1).run()
                    Job().named("a").run()
                    queue.first().run()
                    queue.last.run()
                    either(1).run()
                    each().run()
                """
            },
        )
        assert _calls(builder, "FILE:m.py::run") == [
            "FILE:m.py::Job",
            "FILE:m.py::Job::named",
            *["FILE:m.py::Job::run"] * 4,
            "FILE:m.py::Queue::first",
            "FILE:m.py::each",
            "FILE:m.py::either",
            "FILE:m.py::make",
            "REF:run",
            "REF:run",
        ]

