    def test_standard_method_returns_what_the_data_says(self, tmp_path):
        """`Option<T>::unwrap` gives a `T`, `Vec<T>::first` an `Option<&T>`
        and `HashMap<K, V>::get` an `Option<&V>`: the next call is one on
        that type, and a call on a standard type is the library's."""
        builder = _index(
            tmp_path,
            {
                "src/lib.rs": """
                use std::collections::HashMap;

                pub struct Product;

                impl Product {
                    pub fn ship(&self) {}
                    pub fn len(&self) -> usize { 0 }
                }

                pub struct Decoy;

                impl Decoy {
                    pub fn ship(&self) {}
                    pub fn len(&self) -> usize { 0 }
                }

                pub struct Store {
                    best: Option<Product>,
                    items: Vec<Product>,
                    named: HashMap<String, Product>,
                }

                impl Store {
                    pub fn best(&self) {
                        self.best.as_ref().unwrap().ship();
                    }

                    pub fn first(&self) {
                        self.items.first().unwrap().ship();
                    }

                    pub fn named(&self, name: &str) {
                        self.named.get(name).unwrap().ship();
                    }

                    pub fn size(&self) -> usize {
                        self.items.clone().len() + self.named.keys().len()
                    }
                }
                """
            },
        )
        ship = ["FILE:src/lib.rs::Product::ship"]
        assert _calls(builder, "FILE:src/lib.rs::Store::best") == ship
        assert _calls(builder, "FILE:src/lib.rs::Store::first") == ship
        assert _calls(builder, "FILE:src/lib.rs::Store::named") == ship
        assert _calls(builder, "FILE:src/lib.rs::Store::size") == []

    def test_iterator_keeps_the_type_of_its_items(self, tmp_path):
        """`filter` hands on the items of the iterator it is called on; a
        closure given to `map` returns its block's last expression, after
        statements too."""
        builder = _index(
            tmp_path,
            {
                "src/lib.rs": """
                pub struct Product;

                impl Product {
                    pub fn ship(&self) {}
                    pub fn count(&self) -> usize { 0 }
                }

                pub struct Decoy;

                impl Decoy {
                    pub fn ship(&self) {}
                }

                pub fn kept(items: &[Product]) {
                    items.iter().filter(|p| true).next().unwrap().ship();
                }

                pub fn total(items: Vec<Product>) -> usize {
                    items.iter().rev().skip(1).count()
                }

                pub fn mapped(items: &[Product]) {
                    items.iter().map(|p| { p }).next().unwrap().ship();
                }

                pub fn stated(items: &[Product]) {
                    items.iter().map(|p| { let q = p; q }).next().unwrap().ship();
                }
                """
            },
        )
        assert _calls(builder, "FILE:src/lib.rs::kept") == [
            "FILE:src/lib.rs::Product::ship"
        ]
        assert _calls(builder, "FILE:src/lib.rs::total") == []
        assert _calls(builder, "FILE:src/lib.rs::mapped") == [
            "FILE:src/lib.rs::Product::ship"
        ]
        assert _calls(builder, "FILE:src/lib.rs::stated") == [
            "FILE:src/lib.rs::Product::ship"
        ]

    def test_a_method_whose_dot_ends_the_line_before(self, tmp_path):
        """A call after a `.` that ends the line before is a method of what
        that line ends with, the path the lines before it end with all
        read; after a range's `..` it is the function's, and a `.` that
        starts the line after one is no member of the range's start."""
        builder = _index(
            tmp_path,
            {
                "src/lib.rs": """
                fn n() -> i32 { 1 }
                pub struct S;
                impl S {
                    fn n(&self) -> i32 { 2 }
                    fn me(&self) -> &S { self }
                }
                pub fn run(s: &S) {
                    let t = s.
                        n();
                    let u = s.me().
                        n();
                    let r = 0..
                        n();
                }
                pub struct F;
                impl F { fn n(&self) -> i32 { 3 } }
                pub struct H { pub field: F }
                pub fn hop(h: &H, field: &S) {
                    h.
                        field.
                        n();
                    let r = field..
                        .n();
                }
                """
            },
        )
        assert _calls(builder, "FILE:src/lib.rs::run") == [
            "FILE:src/lib.rs::S::me",
            "FILE:src/lib.rs::S::n",
            "FILE:src/lib.rs::S::n",
            "FILE:src/lib.rs::n",
        ]
        assert _calls(builder, "FILE:src/lib.rs::hop") == [
            "FILE:src/lib.rs::F::n",
            "REF:n",
        ]

    def test_question_mark_takes_the_value_out_of_a_standard_type(self, tmp_path):
        """`?` on an `io::Result<T>` or an `Option<T>` gives a `T`: each
        `?` of `??` in its turn, and one that ends the line before, with or
        without the `.` of the call."""
        builder = _index(
            tmp_path,
            {
                "src/lib.rs": """
                use std::io;

                pub struct Product;

                impl Product {
                    pub fn ship(&self) {}
                }

                pub struct Decoy;

                impl Decoy {
                    pub fn ship(&self) {}
                }

                fn load() -> io::Result<Vec<Product>> { todo!() }

                fn find() -> Option<Option<Product>> { todo!() }

                pub fn run() -> io::Result<()> {
                    load()?.pop().unwrap().ship();
                    Ok(())
                }

                pub fn pick() -> Option<()> {
                    find()??.ship();
                    let found = find()??;
                    found.ship();
                    find()?
                        .unwrap()
                        .ship();
                    find()??.
                        ship();
                    None
                }
                """
            },
        )
        assert _calls(builder, "FILE:src/lib.rs::run") == [
            "FILE:src/lib.rs::Product::ship",
            "FILE:src/lib.rs::load",
        ]
        assert _calls(builder, "FILE:src/lib.rs::pick") == [
            *["FILE:src/lib.rs::Product::ship"] * 4,
            *["FILE:src/lib.rs::find"] * 4,
        ]

