    def test_a_namespace_owns_what_it_declares(self, tmp_path):
        """A namespace, dotted or not, owns its members, which a call names
        through it; one that is a value too, `declare const lib: lib.Api`,
        has the members of the value's type."""
        builder = _index(
            tmp_path,
            {
                "pkg/index.d.ts": """
                declare namespace lib {
                  interface Client { get(url: string): void; }
                  interface Api extends Client { create(): Client; }
                }
                declare const lib: lib.Api;
                export = lib;
                """,
                "a.ts": """
                import lib = require("./pkg");
                function a() {}
                export namespace N {
                  export function f() { a(); }
                }
                namespace A.B {
                  export function g() { a(); }
                }
                export function use() {
                  N.f();
                  A.B.g();
                  lib.get("/x");
                }
                """,
            },
        )
        assert _calls(builder, "FILE:a.ts::N::f") == ["FILE:a.ts::a"]
        assert _calls(builder, "FILE:a.ts::use") == [
            "FILE:a.ts::A::B::g",
            "FILE:a.ts::N::f",
            "FILE:pkg/index.d.ts::lib::Client::get",
        ]

    def test_an_import_binds_what_the_module_exports_under_its_kind(self, tmp_path):
        """A default import is the module's default, whatever it is named;
        a named one is the export of its name, not a name of the module
        itself; a namespace import or a `require` is the module whole, and
        a module that assigns its exports, `export =` or `module.exports =`,
        exports that value's members and that value as its default."""
        builder = _index(
            tmp_path,
            {
                "m.ts": """
                export function run() {}
                export const a = { go() {} };
                const b = { run() {} };
                export default b;
                """,
                "n.ts": """
                export default function foo() {}
                export function named() {}
                """,
                "k.ts": """
                class K { run() {} }
                export default K;
                """,
                "o.js": """
                export default {
                  hello() {}
                };
                """,
                "c.js": """
                function thing() {}
                module.exports = thing;
                """,
                "pkg/index.d.ts": """
                export = React;
                declare namespace React {
                  export function memo(c: any): void;
                }
                """,
                "a.ts": """
                import { a } from "./m";
                import d from "./m";
                import bar from "./n";
                import Kay from "./k";
                import * as N from "./n";
                import obj from "./o.js";
                import { memo } from "./pkg";
                import * as R from "./pkg";
                import Q = require("./pkg");
                const t = require("./c.js");
                export function use(k: Kay) {
                  a.run();
                  a.go();
                  d.run();
                  bar();
                  N.named();
                  k.run();
                  obj.hello();
                  t();
                  memo(1);
                  R.memo(2);
                  Q.memo(3);
                }
                """,
            },
        )
        assert _calls(builder, "FILE:a.ts::use") == [
            "FILE:c.js::thing",
            "FILE:k.ts::K::run",
            "FILE:m.ts::a::go",
            "FILE:m.ts::b::run",
            "FILE:n.ts::foo",
            "FILE:n.ts::named",
            "FILE:o.js::object@2::hello",
            "FILE:pkg/index.d.ts::React::memo",
            "FILE:pkg/index.d.ts::React::memo",
            "FILE:pkg/index.d.ts::React::memo",
            "REF:a.run",
        ]

