    def test_a_go_generic_type_holds_its_type_arguments(self, tmp_path):
        """`Box[Cat]`'s `T` is a cat through a field, a method's return, a
        pointer receiver, a field declared `Box[Cat]`, a composite literal,
        a `var` and a generic function called with its type arguments; a
        method's receiver names the parameters by position, and a
        constraint bounds `T` inside its type."""
        builder = _index(
            tmp_path,
            {
                "go.mod": "module example.com/g\n\ngo 1.21\n",
                "a.go": """
                package g

                type Dog struct{}

                func (d Dog) Bark() {}

                type Cat struct{}

                func (c Cat) Meow() {}

                type Speaker interface{ Speak() }

                type Box[T any] struct{ Held T }

                func (b Box[T]) Get() T       { return b.Held }
                func (b *Box[T]) Me() *Box[T] { return b }
                func (b Box[U]) Peek() U      { return b.Held }

                func NewBox[T any](v T) Box[T] { return Box[T]{Held: v} }

                type Coop[T Speaker] struct{ held T }

                func (c Coop[T]) Go() { c.held.Speak() }

                type Holder struct{ B Box[Cat] }

                func Run(b Box[Cat], h Holder, p *Box[Cat]) {
                	b.Held.Meow()
                	b.Me().Get().Meow()
                	b.Peek().Meow()
                	h.B.Get().Meow()
                	p.Get().Meow()
                	local := Box[Dog]{Held: Dog{}}
                	local.Get().Bark()
                	made := NewBox[Dog](Dog{})
                	made.Get().Bark()
                	var v Box[Dog]
                	v.Get().Bark()
                }
                """,
            },
        )
        calls = _calls(builder, "FILE:a.go::Run")
        assert calls.count("FILE:a.go::Cat::Meow") == 5
        assert calls.count("FILE:a.go::Dog::Bark") == 3
        assert _calls(builder, "FILE:a.go::Coop::Go") == ["FILE:a.go::Speaker::Speak"]

    def test_typescript_arrow_annotations_and_scopes(self, tmp_path):
        """An arrow typed by a union of function types, or by a generic one,
        has parameters of no known type; by an intersection, those of its
        one function type, its body its own on its line. A name a pattern
        binds with a default is no global. A function another returns is a
        scope of its own. A parameter is in scope in the
        functions its definition holds, not in the file."""
        builder = _index(
            tmp_path,
            {
                "a.ts": """
                export class Dog { bark() {} }
                export class Cat { meow() {} }
                export interface AProps { run(): void }
                export function curry(f: (d: Dog) => () => void) {}
                export const u: ((x: Dog) => void) | ((x: Cat) => void) = (x) => { x.bark(); };
                export const g: <T>(x: T) => void = (x) => { x.meow(); };
                export const i: ((x: Dog) => void) & { n?: number } = (x) => { x.bark(); };
                export function deflt() {
                  const { status = new Dog() } = { status: new Dog() };
                  status.bark();
                }
                export function run() {
                  curry((d) => () => {
                    d.bark();
                  });
                }
                export const A = (props: AProps) => {
                  const inner = () => {
                    props.run();
                  };
                  inner();
                };
                export function B() {
                  props.run();
                }
                """
            },
        )
        assert _calls(builder, "FILE:a.ts::u") == ["REF:x.bark"]
        assert _calls(builder, "FILE:a.ts::g") == ["REF:x.meow"]
        assert _calls(builder, "FILE:a.ts::i") == ["FILE:a.ts::Dog::bark"]
        assert "REF:status.bark" in _calls(builder, "FILE:a.ts::deflt")
        assert _calls(builder, "FILE:a.ts::run::callback@14") == [
            "FILE:a.ts::Dog::bark"
        ]
        assert _calls(builder, "FILE:a.ts::A::inner") == ["FILE:a.ts::AProps::run"]
        assert _calls(builder, "FILE:a.ts::B") == ["REF:props.run"]

    def test_typescript_scopes_of_one_line_definitions(self, tmp_path):
        """A parameter of a definition on one line is that definition's, the
        siblings declared beside it read their own; the calls after a `;`
        a one-line arrow's body holds are the arrow's, and a binding its
        head makes holds there."""
        builder = _index(
            tmp_path,
            {
                "a.ts": """
                class A { use() { return 1; } helper() {} }
                class B { run() { return 1; } }
                type Pair = (a: A, b: A) => void;
                function declared(x: A) {} function noParam() { x.use(); }
                const p = (x: A) => x.use(); function later() { x.use(); }
                const f = (x: A) => x.use(), g = (x: B) => x.run();
                const k: Pair = (a, b) => { a.use(); b.use(); };
                """
            },
        )
        assert _calls(builder, "FILE:a.ts::noParam") == ["REF:x.use"]
        assert _calls(builder, "FILE:a.ts::later") == ["REF:x.use"]
        assert _calls(builder, "FILE:a.ts::g") == ["FILE:a.ts::B::run"]
        assert _calls(builder, "FILE:a.ts::k") == ["FILE:a.ts::A::use"] * 2

    def test_typescript_declarators_bodies_and_heads(self, tmp_path):
        """A first declarator is typed by its value as a later one is, and
        `typeof x` by what `x` is declared as; a one-line namespace body
        and an object whose `{` opens on the next line own their members;
        a `for` head binds its names for a body on its line; an arrow's own
        parameters read its annotation over lines and its rest parameter
        an array; a construction followed by a call types no name."""
        builder = _index(
            tmp_path,
            {
                "a.ts": """
                class A { use() { return 1; } }
                class Box { open(): Box | number { return this; } }
                const single = new A();
                const d = new A();
                namespace N { export function m() { single.use(); } }
                const o =
                {
                  m() { single.use(); }
                };
                type Fn = (
                  a: A,
                ) => void;
                const h: Fn = e => { e.use(); };
                const h2: (a: A) => void = (
                  e,
                ) => { e.use(); };
                const each: (...dogs: A[]) => void = (...all) => {
                  all[0].use();
                };
                export function caller(x: typeof d, items: A[]) {
                  const alias = single;
                  alias.use();
                  x.use();
                  for (const i of items) { i.use(); }
                  o.m();
                  const opened = new Box().open();
                  opened.use();
                }
                """
            },
        )
        use = "FILE:a.ts::A::use"
        assert _calls(builder, "FILE:a.ts::caller").count(use) == 3
        assert "FILE:a.ts::o::m" in _calls(builder, "FILE:a.ts::caller")
        assert "REF:opened.use" in _calls(builder, "FILE:a.ts::caller")
        assert _calls(builder, "FILE:a.ts::N::m") == [use]
        for name in ("h", "h2", "each"):
            assert _calls(builder, f"FILE:a.ts::{name}") == [use]

