        assert {"FILE:a.ts::o::m", "FILE:a.ts::o::n"} <= set(calls)
        later = "FILE:a.ts::Outer::callback@21::later"
        assert _calls(builder, later) == ["FILE:a.ts::Outer::callback@21::on"]

