        assert _calls(builder, "FILE:src/Builder.php::Client::run") == [
            "FILE:src/Builder.php::Builder::build",
            "FILE:src/Builder.php::Builder::find",
            "FILE:src/Builder.php::Builder::last",
            "FILE:src/Builder.php::Builder::named",
            "FILE:src/Builder.php::Builder::named",
            ship,
            ship,
            "REF:ship",
        ]

