    def test_the_overload_the_arguments_match_exactly_is_called(self, tmp_path):
        """Of overloads that take as many arguments, the one whose parameters
        are each of its argument's type, the one a `null` can be passed to,
        or the one alone the arguments convert to; open where none or
        several are, or an argument's type is not known."""
        builder = _index(
            tmp_path,
            {
                "W.cs": """
                public class Writer
                {
                    public void Write(int value) { }
                    public void Write(long value) { }
                    public void Write(string? value) { }
                }
                public class Use
                {
                    void Run(Writer w, int count, string name, object thing)
                    {
                        w.Write(1);
                        w.Write(1L);
                        w.Write("a");
                        w.Write(count);
                        w.Write(name);
                        w.Write(null);
                        w.Write(thing);
                        w.Write(3000000000);
                    }
                }
                """,
            },
        )
        found = [
            e["target"].rpartition("::")[2]
            for e in builder.edges
            if e["source"] == "FILE:W.cs::Use::Run"
        ]
        assert found == [
            "Write",
            "Write#2",
            "Write#3",
            "Write",
            "Write#3",
            "Write#3",
            "REF:w.Write",
            # A `uint` literal widens to `long`, not to `int`.
            "Write#2",
        ]

    def test_overloads_that_take_as_many_arguments(self, tmp_path):
        """A call that several overloads can take is left open with them as
        candidates; the arguments of one are counted to the `)` that closes
        them."""
        builder = _index(
            tmp_path,
            {
                "Box.cs": """
                public class Box
                {
                    public void Put(int item) { }
                    public void Put(string item) { }
                    public void Put(int item, int at) { }
                    void Run(object x) {
                        Put(x);
                        Put("a, b",
                            2);
                    }
                }
                """,
            },
        )
        (open_call, two) = [
            e for e in builder.edges if e["source"] == "FILE:Box.cs::Box::Run"
        ]
        assert open_call["target"] == "REF:Put"
        assert open_call["metadata"]["candidates"] == [
            "FILE:Box.cs::Box::Put",
            "FILE:Box.cs::Box::Put#2",
        ]
        assert two["target"] == "FILE:Box.cs::Box::Put#3"

    def test_generic_type_from_outside(self, tmp_path):
        """A member of `List<Order>` is the list's; what it returns may be
        an Order, so a call on that is not dropped. A `Task<Order>` awaited
        is an Order; so may be what a generic method from outside returns."""
        builder = _index(
            tmp_path,
            {
                "Order.cs": """
                public class Order
                {
                    public void Add(int item) { }
                    public void Ship() { }
                }

                public class Orders
                {
                    public Task<Order> LoadAsync() => null;
                    public List<Order> All { get; }
                }

                public class Decoy
                {
                    public void Ship() { }
                }
                """,
                "Client.cs": """
                public class Client
                {
                    async Task Run(Orders orders, IServiceProvider services)
                    {
                        orders.All.Add(null);
                        orders.All.First().Ship();
                        var loaded = await orders.LoadAsync();
                        loaded.Ship();
                        services.GetService<Order>().Ship();
                    }
                }
                """,
            },
        )
        assert _calls(builder, "FILE:Client.cs::Client::Run") == [
            "FILE:Order.cs::Order::Ship",
            "FILE:Order.cs::Orders::LoadAsync",
            "REF:Ship",
            "REF:Ship",
        ]

