        assert _calls(builder, "FILE:lib/shape.dart::ends") == [
            ci,
            "FILE:lib/shape.dart::Shape::name",
            side,
        ]
        assert _calls(builder, "FILE:lib/shape.dart::leaves") == [ci, side]
        assert _calls(builder, "FILE:lib/shape.dart::block") == [ci, side]

